#!/usr/bin/env python3
"""Render a visual showcase of brand-new multi-panel comics generated by xkcd-artist."""

from pathlib import Path
from PIL import Image, ImageDraw, ImageFont

ROOT = Path(__file__).resolve().parent.parent
FONT_PATH = ROOT / "docs" / "fonts" / "xkcd-script.ttf"
OUT = ROOT / "docs" / "samples" / "hybrid_lora_showcase.png"


def get_font(size: int):
    if FONT_PATH.exists():
        try:
            return ImageFont.truetype(str(FONT_PATH), size=size)
        except Exception:
            pass
    return ImageFont.load_default()


def main() -> None:
    W, H = 1400, 920
    canvas = Image.new("RGB", (W, H), (246, 245, 239))
    draw = ImageDraw.Draw(canvas)

    f_title = get_font(28)
    f_sub = get_font(15)
    f_card = get_font(15)

    draw.text(
        (36, 20),
        "XKCD-ARTIST // NOVEL MULTI-PANEL COMIC GENERATION FROM ARBITRARY PROMPTS",
        fill=(17, 17, 17),
        font=f_title,
    )
    draw.text(
        (36, 56),
        "Synthesizes multi-panel visual progressions (3-panel escalation, 4-panel code review, 3-panel debate, team demo) + xkcd-script.ttf dialogue",
        fill=(80, 80, 80),
        font=f_sub,
    )

    cards = [
        ("Novel Prompt: 'Why my Docker container image is 18GB'", ROOT / "docs" / "samples" / "novel_docker.png"),
        ("Novel Prompt: 'Reviewing a 4200 line pull request in TypeScript'", ROOT / "docs" / "samples" / "novel_pr_review.png"),
        ("Novel Prompt: 'Autonomous AI agents automating my workflow'", ROOT / "docs" / "samples" / "novel_agents.png"),
        ("Novel Prompt: 'Git rebase before release'", ROOT / "docs" / "samples" / "novel_git_rebase.png"),
    ]

    cw, ch = 648, 386
    for idx, (label, path) in enumerate(cards):
        row = idx // 2
        col = idx % 2
        x0 = 36 + col * (cw + 32)
        y0 = 96 + row * (ch + 24)
        draw.rectangle([x0 + 4, y0 + 4, x0 + cw + 4, y0 + ch + 4], fill=(17, 17, 17))
        draw.rectangle([x0, y0, x0 + cw, y0 + ch], fill=(255, 255, 255), outline=(17, 17, 17), width=2)
        draw.text((x0 + 14, y0 + 10), label.upper(), fill=(17, 17, 17), font=f_card)

        if path.exists():
            im = Image.open(path).convert("RGB")
            im.thumbnail((cw - 24, ch - 46), Image.Resampling.LANCZOS)
            px = x0 + (cw - im.width) // 2
            py = y0 + 36 + (ch - 46 - im.height) // 2
            canvas.paste(im, (px, py))

    OUT.parent.mkdir(parents=True, exist_ok=True)
    canvas.save(OUT)
    print(f"Saved showcase to {OUT}")


if __name__ == "__main__":
    main()
